entries[30547] = { ["name"] = "Elementare Zephyriumladung", ["text"] = "Wirken in 12.5 sek.\nReagenzien:\nElementarsprengpulver (2), Teufelseisengehäuse , Eine Hand voll Teufelseisenbolzen\n(2)\nBenötigt Ingenieurskunst\n(350)\nBenutzen: Sprengt bis auf die stärksten alle verschlossenen Türen und Truhen auf." }
entries[30548] = { ["name"] = "Schockdrosselnder Partikelextraktor", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse (2), Eine Hand voll Teufelseisenbolzen (2), Urleben (4), Empfindlicher Arkanitwandler\nBenötigt Ingenieurskunst\n(305)\nBenutzen: Extrahiert Gas aus einer in der Nähe befindlichen Gaswolke." }
