entries[30551] = { ["name"] = "Heiltrankeinspritzung", ["text"] = "Wirken in 25 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse , Eine Hand voll Teufelseisenbolzen , Knotenhautleder (2), Erstklassiger Heiltrank (20)\n(20)\n55\nBenutzen: Stellt 1500 bis 2500 Gesundheit wieder her. (2 Min Abklingzeit)" }
